"""Author complete discovery handlers in HIA; no retained business-body call."""
from __future__ import annotations
import ast
from pathlib import Path
import re
import sys
ROOT = Path(__file__).resolve().parents[1]
if __package__ in (None, ''):
    sys.path.insert(0, str(ROOT))
from hepta.hia_agent_assembly import render_assembly
from hepta.hia_service_discovery_protocol import (
    PORT, REQUEST_MAGIC, RESULT_MAGIC, STATE_MAGIC, SOURCE_NAME)
from tools.generate_hia_selfhost import compact_authoring_cfg, total_scalar_functions
from tools.generate_hia_service_context import ContextBuilder

PROTOCOL = 'def service_discovery(s:readbuf, o:mutbuf, w:mutbuf) -> u32:\n    if length(s) != 128 or length(o) != 96 or length(w) != 192:\n        return 4294967293\n    if read_word(s, 0) != @REQUEST_MAGIC@:\n        return 4294967293\n    index = 64\n    while index < 128:\n        if read_word(s, index) != 0:\n            return 4294967293\n        index = index + 8\n    event = read_word(s, 8)\n    if event == 0:\n        return initialize(s, o, w)\n    if valid_state(w) == 0:\n        return 4294967293\n    if read_word(s, 40) != get(w, 2) or read_word(s, 48) != get(w, 6) or read_word(s, 56) != get(w, 7):\n        return refuse(o, w)\n    if read_word(s, 16) != get(w, 4) or read_word(s, 24) != get(w, 3):\n        return refuse(o, w)\n    observed = read_word(s, 32)\n    phase = get(w, 5)\n    port = get(w, 3)\n    if event == 1:\n        if phase != 1 or observed != 0:\n            return refuse(o, w)\n        set(w, 5, 2)\n        seal(w)\n        return answer(o, w, 0)\n    if event == 2:\n        if phase != 2:\n            return refuse(o, w)\n        if boolean_port(port) == 1:\n            if observed > 1:\n                return refuse(o, w)\n        elif observed != 0:\n            return refuse(o, w)\n        return succeeded(o, w, observed)\n    if event == 3:\n        if phase != 2 or observed != 0:\n            return refuse(o, w)\n        set(w, 12, 1)\n        return advance(o, w, 0, 7)\n    if event == 4:\n        if port != 0 or observed != 0:\n            return refuse(o, w)\n        if phase == 6:\n            return advance(o, w, 0, 4)\n        if phase == 7:\n            return advance(o, w, 0, 5)\n        return refuse(o, w)\n    return refuse(o, w)\n\ndef initialize(s:readbuf, o:mutbuf, w:mutbuf) -> u32:\n    mode = read_word(s, 40)\n    if mode != 1 and mode != 2:\n        return 4294967293\n    if read_word(s, 16) != 0 or read_word(s, 24) != 0 or read_word(s, 32) != 0:\n        return 4294967293\n    if read_word(s, 48) == 0 and read_word(s, 56) == 0:\n        return 4294967293\n    index = 0\n    while index < 192:\n        if byte(w, index) != 0:\n            return 4294967293\n        index = index + 1\n    set(w, 0, @STATE_MAGIC@)\n    set(w, 1, 1)\n    set(w, 2, mode)\n    if mode == 1:\n        set(w, 3, @describe_import@)\n    else:\n        set(w, 3, @examples_import@)\n    set(w, 4, 1)\n    set(w, 5, 1)\n    set(w, 6, read_word(s, 48))\n    set(w, 7, read_word(s, 56))\n    seal(w)\n    return answer(o, w, 0)\n\ndef owned_port(mode:u64, port:u64) -> u64:\n    if mode == 1:\n        if port >= @describe_import@ and port <= @describe_release@:\n            return 1\n    if mode == 2:\n        if port >= @examples_import@ and port <= @examples_release@:\n            return 1\n    return 0\n\ndef valid_state(w:mutbuf) -> u64:\n    if get(w, 0) != @STATE_MAGIC@ or get(w, 1) != 1:\n        return 0\n    mode = get(w, 2)\n    if mode != 1 and mode != 2:\n        return 0\n    phase = get(w, 5)\n    port = get(w, 3)\n    if get(w, 4) == 0 or phase == 0 or phase == 3 or phase > 8:\n        return 0\n    if get(w, 8) != 0 or get(w, 9) != 0 or get(w, 11) != 0 or get(w, 12) > 1:\n        return 0\n    index = 13\n    while index < 24:\n        if get(w, index) != 0:\n            return 0\n        index = index + 1\n    if checksum(w) != get(w, 10):\n        return 0\n    if phase == 1 or phase == 2:\n        if owned_port(mode, port) == 0 or get(w, 12) != 0:\n            return 0\n    elif port != 0:\n        return 0\n    if phase == 4 or phase == 6:\n        if get(w, 12) != 0:\n            return 0\n    if phase == 5 or phase == 7:\n        if get(w, 12) != 1:\n            return 0\n    return 1\n\ndef boolean_port(port:u64) -> u64:\n    if port == @describe_cursor@:\n        return 1\n    if port == @describe_backend_present@:\n        return 1\n    if port == @describe_backend_differs@:\n        return 1\n    if port == @examples_roundtrip_differs@:\n        return 1\n    return 0\n\ndef succeeded(o:mutbuf, w:mutbuf, observed:u64) -> u32:\n    port = get(w, 3)\n    if port <= @describe_language@:\n        return continuation_1(o, w, observed)\n    if port <= @examples_document@:\n        return continuation_2(o, w, observed)\n    if port <= @examples_release@:\n        return continuation_3(o, w, observed)\n    return refuse(o, w)\n\ndef continuation_1(o:mutbuf, w:mutbuf, observed:u64) -> u32:\n    port = get(w, 3)\n    if port == @describe_import@:\n        return advance(o, w, @describe_cursor@, 1)\n    if port == @describe_cursor@:\n        if observed == 1:\n            return advance(o, w, @describe_reject_cursor@, 1)\n        return advance(o, w, @describe_backend_present@, 1)\n    if port == @describe_reject_cursor@:\n        return advance(o, w, @describe_backend_present@, 1)\n    if port == @describe_backend_present@:\n        if observed == 1:\n            return advance(o, w, @describe_backend_differs@, 1)\n        return advance(o, w, @describe_language_schema@, 1)\n    if port == @describe_backend_differs@:\n        if observed == 1:\n            return advance(o, w, @describe_reject_backend@, 1)\n        return advance(o, w, @describe_language_schema@, 1)\n    if port == @describe_reject_backend@:\n        return advance(o, w, @describe_language_schema@, 1)\n    if port == @describe_language_schema@:\n        return advance(o, w, @describe_language@, 1)\n    if port == @describe_language@:\n        return advance(o, w, @describe_profile@, 1)\n    return refuse(o, w)\n\ndef continuation_2(o:mutbuf, w:mutbuf, observed:u64) -> u32:\n    port = get(w, 3)\n    if port == @describe_profile@:\n        return advance(o, w, @describe_section@, 1)\n    if port == @describe_section@:\n        return advance(o, w, @describe_resources@, 1)\n    if port == @describe_resources@:\n        return advance(o, w, @describe_result@, 1)\n    if port == @describe_result@:\n        return advance(o, w, @describe_release@, 1)\n    if port == @describe_release@:\n        return advance(o, w, 0, 6)\n    if port == @examples_import@:\n        return advance(o, w, @examples_params@, 1)\n    if port == @examples_params@:\n        return advance(o, w, @examples_document@, 1)\n    if port == @examples_document@:\n        return advance(o, w, @examples_program@, 1)\n    return refuse(o, w)\n\ndef continuation_3(o:mutbuf, w:mutbuf, observed:u64) -> u32:\n    port = get(w, 3)\n    if port == @examples_program@:\n        return advance(o, w, @examples_assembly@, 1)\n    if port == @examples_assembly@:\n        return advance(o, w, @examples_roundtrip_differs@, 1)\n    if port == @examples_roundtrip_differs@:\n        if observed == 1:\n            return advance(o, w, @examples_raise_roundtrip@, 1)\n        return advance(o, w, @examples_result@, 1)\n    if port == @examples_raise_roundtrip@:\n        return advance(o, w, @examples_result@, 1)\n    if port == @examples_result@:\n        return advance(o, w, @examples_release@, 1)\n    if port == @examples_release@:\n        return advance(o, w, 0, 6)\n    return refuse(o, w)\n\ndef advance(o:mutbuf, w:mutbuf, port:u64, phase:u64) -> u32:\n    if get(w, 4) == 18446744073709551615:\n        return refuse(o, w)\n    set(w, 3, port)\n    set(w, 4, get(w, 4) + 1)\n    set(w, 5, phase)\n    seal(w)\n    return answer(o, w, 0)\n\ndef refuse(o:mutbuf, w:mutbuf) -> u32:\n    set(w, 3, 0)\n    set(w, 5, 8)\n    seal(w)\n    return answer(o, w, 1)\n\ndef answer(o:mutbuf, w:mutbuf, status:u64) -> u32:\n    set(o, 0, @RESULT_MAGIC@)\n    set(o, 1, status)\n    set(o, 2, get(w, 3))\n    set(o, 3, get(w, 4))\n    set(o, 4, get(w, 5))\n    set(o, 5, get(w, 2))\n    set(o, 6, get(w, 12))\n    set(o, 7, 0)\n    set(o, 8, get(w, 6))\n    set(o, 9, get(w, 7))\n    set(o, 10, 0)\n    set(o, 11, 0)\n    return 96\n\ndef checksum(w:mutbuf) -> u64:\n    value = 1469598103934665603\n    index = 0\n    while index < 24:\n        if index != 10:\n            value = ((value << 7) | (value >> 57)) ^ get(w, index)\n        index = index + 1\n    return value\n\ndef seal(w:mutbuf) -> u64:\n    value = checksum(w)\n    set(w, 10, value)\n    return value\n\ndef read_word(s:readbuf, index:u64) -> u64:\n    value = 0\n    shift = 0\n    while shift < 8:\n        value = value | (byte(s, index + shift) << (shift * 8))\n        shift = shift + 1\n    return value\n\ndef get(w:mutbuf, index:u64) -> u64:\n    value = 0\n    shift = 0\n    while shift < 8:\n        value = value | (byte(w, index * 8 + shift) << (shift * 8))\n        shift = shift + 1\n    return value\n\ndef set(w:mutbuf, index:u64, value:u64) -> u64:\n    shift = 0\n    while shift < 8:\n        store(w, index * 8 + shift, value >> (shift * 8))\n        shift = shift + 1\n    return value\n'

def source_program():
    values = {**PORT, 'REQUEST_MAGIC': REQUEST_MAGIC,
              'RESULT_MAGIC': RESULT_MAGIC, 'STATE_MAGIC': STATE_MAGIC}
    return re.sub(r'@([A-Za-z_][A-Za-z_0-9]*)@',
                  lambda match: str(values[match[1]]), PROTOCOL)

def document():
    nodes = ast.parse(source_program()).body
    names = {node.name: 'f' + str(index) for index, node in enumerate(nodes)}
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args],
                             node.returns.id) for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = ContextBuilder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name],
            'params': [builder.param(value) for value in builder.params],
            'returns': [builder.returns], 'effects': ['read', 'write', 'trap'],
            'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8',
        'module': 'service_discovery', 'functions': functions})

if __name__ == '__main__':
    path = ROOT / SOURCE_NAME
    path.write_text(render_assembly(document()))
    print(path.name, path.stat().st_size)
